void Ordnance::GetDamage(DAMAGE &dmg, ENTITY *hit)
{
    // fill in basic damage
    ENTITY::GetDamage(dmg, hit);

    // get ordnance damage
    dmg.base = GetOrdnanceClass()->damageValue;
    dmg.armor = GetOrdnanceClass()->armorScale[hit->flags.armor];
    dmg.shield = GetOrdnanceClass()->shieldScale[hit->flags.shield];
    dmg.value = dmg.base * dmg.armor * dmg.shield;
}```

